"""Native health/aura ownership, allied build children and objective lifecycle."""
from pathlib import Path
import unittest
import test_asxui_hud as hud
ROOT=hud.ROOT

class FramesTests(unittest.TestCase):
    def run_lua(self,s):self.lua.execute(s)
    def setUp(self):
        hud.HUDTests.setUp(self)
        self.lua.execute('''
for i=1,4 do local p=objects["PartyMemberFrame"..i];_G["PartyMemberFrame"..i]=p;function p:GetFrameLevel()return 5 end;function p:GetNumPoints()return self.anchor and 1 or 0 end;function p:GetPoint()return unpack(self.anchor or{})end end
TargetFrame=CreateFrame("Frame","TargetFrame",UIParent)
function UnitHealth()return playerHP or 125 end
function UnitHealthMax()return 250 end
function TargetFrame:IsMouseEnabled()return self.mouse~=false end
function PlayerFrame:IsMouseEnabled()return self.mouse~=false end
Minimap=CreateFrame("Frame","Minimap",UIParent)
guardians={{name="Ancient Guardian",hp=100},{name="Fallen Guardian",hp=0}}
function AZS_GetGuardians()return guardians end
view.data.sayge={event=1,held=0,maximum=2000}
for i=0,3 do local f=CreateFrame("Button","BuffButton"..i,UIParent);f.buffFilter=i==3 and "HARMFUL"or"HELPFUL";f.buffIndex=i;f:SetWidth(32);f:SetHeight(32);f:SetPoint("TOP",UIParent,"TOP",i*40,0);f.nativeClick=function()end;f.scripts.OnClick=f.nativeClick;local t=CreateFrame("FontString","BuffButton"..i.."Duration",UIParent);t:SetPoint("TOP",f,"BOTTOM",0,0)end
''')
        self.lua.execute((ROOT/'addons/ASXUI/Theme.lua').read_text())
        self.lua.execute((ROOT/'addons/ASXUI/Frames.lua').read_text())
        self.lua.execute('arg1=.1;ASXUIFramesController.scripts.OnUpdate();ASXUI_DockAuras(view);arg1=.1;ASXUIFramesController.scripts.OnUpdate()')
    def test_character_level_uses_native_run_value_and_clears_invalid_data(self):
        self.lua.execute('AZS_RUN.lvl=42;arg1=.2;ASXUIFramesController.scripts.OnUpdate();assert(ASXUI_FramesReadout().level=="Lv 42");AZS_RUN.lvl=0/0;arg1=.2;ASXUIFramesController.scripts.OnUpdate();assert(ASXUI_FramesReadout().level=="")')
    def test_hp_only_native_values_and_root_restoration(self):
        self.run_lua('assert(PlayerFrame:GetAlpha()==0 and TargetFrame:GetAlpha()==0);assert(ASXUIHudHealth.fraction==.5 and ASXUIHudHealth:GetWidth()==143.5);assert(ASXUIHudHealth:GetHeight()==22 and ASXUIHudHealthFill:GetWidth()==287 and ASXUIHudHealth.anchor[1]=="LEFT");playerHP=0;arg1=.1;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIHudHealth.fraction==0 and not ASXUIHudHealth:IsShown());ASXUI_ConfigureHud("off");ASXUIFramesController.scripts.OnUpdate();assert(PlayerFrame:GetAlpha()==1 and TargetFrame:GetAlpha()==1 and PlayerFrame:IsMouseEnabled() and TargetFrame:IsMouseEnabled())')
    def test_pill_fill_clips_its_fixed_silhouette_at_low_full_and_missing_health(self):
        self.run_lua('assert(ASXUIHudHealthFillLeft1.texture=="Interface\\\\CharacterFrame\\\\TempPortraitAlphaMask" and ASXUIHudHealthFillRight22.texture==ASXUIHudHealthFillLeft1.texture and ASXUIHudHealthFill.centerTexture.texture=="Interface\\\\ChatFrame\\\\ChatFrameBackground");playerHP=1;arg1=.1;ASXUIFramesController.scripts.OnUpdate();assert(math.abs(ASXUIHudHealth:GetWidth()-287/250)<.001 and ASXUIHudHealthFill:GetWidth()==287);playerHP=300;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIHudHealth:GetWidth()==287);function UnitHealthMax()return nil end;ASXUIFramesController.scripts.OnUpdate();assert(not ASXUIHudHealth:IsShown() and ASXUI_FramesReadout().health=="—")')
    def test_auras_keep_native_ids_scripts_and_separate_harmful_row(self):
        self.run_lua('assert(BuffButton0.scripts.OnClick==BuffButton0.nativeClick);assert(BuffButton3.buffIndex==3 and BuffButton3.buffFilter=="HARMFUL");assert(BuffButton3.anchor[5]>BuffButton0.anchor[5]);ASXUI_ConfigureHud("off");assert(not ASXUI_DockAuras(view));assert(BuffButton0.anchor[2]==UIParent and BuffButton0Duration.anchor[1]=="TOP" and BuffButton0Duration.anchor[3]=="BOTTOM")')
    def test_compact_vitals_center_each_aura_row_without_shrinking_native_buttons(self):
        self.run_lua('assert(ASXUIHudVitals:GetWidth()==291 and ASXUI_GetHudAnchors().width==437);assert(BuffButton0.anchor[3]=="BOTTOM" and BuffButton0.anchor[4]==59);assert(BuffButton2.anchor[4]==-27 and BuffButton3.anchor[4]==16);for i=4,10 do local f=CreateFrame("Button","BuffButton"..i,UIParent);f:SetWidth(32);f:SetHeight(32);f.buffFilter="HELPFUL"end;ASXUI_DockAuras(view);assert(BuffButton9.anchor[4]==37.5 and BuffButton10.anchor[4]==-5.5 and BuffButton9.anchor[5]>BuffButton0.anchor[5]);assert(BuffButton0:GetWidth()==32 and BuffButton0.scripts.OnClick==BuffButton0.nativeClick);ASXUI_ConfigureHud("off");ASXUI_DockAuras(view);assert(BuffButton0.anchor[2]==UIParent and BuffButton0Duration.anchor[1]=="TOP" and BuffButton0Duration.anchor[3]=="BOTTOM")')
    def test_fixed_health_and_drawer_between_equipment_and_native_gryphons(self):
        self.run_lua('assert(ASXUIHudVitals.anchor[2]==UIParent and ASXUIHudVitals.anchor[5]==184);local before=ASXUIHudVitals.anchor[5];hudCall("ASXUIHudStats","OnClick");hudTick();arg1=.1;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIHudVitals.anchor[5]==before);assert(ASXUIHudAuras.anchor[2]==ASXUIHudVitals and ASXUIHudAuras.anchor[3]=="TOP");assert(BuffButton0Duration.anchor[1]=="BOTTOM" and BuffButton0Duration.anchor[2]==BuffButton0 and BuffButton0Duration.anchor[3]=="TOP");assert(ASXUIHudDrawer:GetFrameLevel()>ASXUIHudEquipment1:GetFrameLevel() and ASXUIHudDrawer:GetFrameLevel()<MainMenuBarArtFrame:GetFrameLevel());local anchor,y=ASXUI_GetDrawerAnchor();assert(anchor==ASXUIHudBase and y==0 and ASXUIHudDrawerMask.anchor[2]==ASXUIHudBase)')
    def test_bosses_and_awake_guardians_follow_top_hud_and_fail_open(self):
        self.run_lua('hudPrefs.bosses=true;bosses={{id=1,name="Boss",hp=30,hpm=100}};function AZS_GetBosses()return bosses end;guardians={{id=2,name="Guardian",hp=50,hpm=200,awake=true},{id=3,name="Sleeping",hp=100,hpm=100,awake=false}};arg1=.2;ASXUIFramesController.scripts.OnUpdate();assert(not hudPrefs.bosses and ASXUIEncounters:IsShown() and ASXUIEncounter1.title.text=="Boss" and ASXUIEncounter1.bar.value==.3 and ASXUIEncounter2.title.text=="Guardian" and ASXUIEncounter2.bar.value==.25);assert(ASXUIEncounters.anchor[5]==-132 and ASXUI_GetEncounterOffset()==206);bosses[1].hpm=nil;ASXUIFramesController.scripts.OnUpdate();assert(hudPrefs.bosses and not ASXUIEncounters:IsShown() and ASXUI_GetEncounterOffset()==137);bosses[1].hpm=100;ASXUIFramesController.scripts.OnUpdate();ASXUI_ConfigureHud("off");ASXUIFramesController.scripts.OnUpdate();assert(hudPrefs.bosses and not ASXUIEncounters:IsShown())')
    def test_native_goblin_health_joins_encounters_without_selecting_other_elites(self):
        self.run_lua('hudPrefs.bosses=true;function AZS_GetBosses()return {}end;guardians={};AZS_UNITS={{kind="elite",id=123,name="Venture Co. Treasurer",hp=30,hpm=120},{kind="elite",id=124,name="Other elite",hp=50,hpm=100},{kind="normal",id=125,name="Venture Co. Treasurer",hp=50,hpm=100}};arg1=.2;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIEncounters:IsShown() and ASXUIEncounter1.title.text=="Venture Co. Treasurer" and ASXUIEncounter1.bar.value==.25 and ASXUI_GetEncounterOffset()==175);AZS_UNITS[1].hp=0;ASXUIFramesController.scripts.OnUpdate();assert(not ASXUIEncounters:IsShown());AZS_UNITS[1].hp=30;AZS_UNITS[1].hpm=nil;ASXUIFramesController.scripts.OnUpdate();assert(hudPrefs.bosses and not ASXUIEncounters:IsShown())')
    def test_encounter_overflow_preserves_complete_native_display(self):
        self.run_lua('hudPrefs.bosses=true;function AZS_GetBosses()local out={};for i=1,9 do out[i]={id=i,name="Boss",hp=1,hpm=2}end;return out end;guardians={};arg1=.2;ASXUIFramesController.scripts.OnUpdate();assert(hudPrefs.bosses and not ASXUIEncounters)')
    def test_objectives_only_include_living_guardians_and_available_ritual(self):
        self.run_lua('assert(ASXUIObjectives:IsShown() and ASXUIObjectives:GetHeight()==164);guardians={};view.data.sayge=nil;arg1=.1;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIObjectives:IsShown() and ASXUI_FramesReadout().objectives[1]=="No active objectives")')
    def test_objective_tracker_follows_minimap_without_moving_allies_across_screen(self):
        self.run_lua('assert(ASXUIObjectives.anchor[1]=="TOPRIGHT" and ASXUIObjectives.anchor[2]==Minimap and ASXUIObjectives.anchor[3]=="BOTTOMRIGHT");assert(PartyMemberFrame1.anchor[2]==UIParent and PartyMemberFrame1.anchor[1]=="TOPLEFT");MinimapCluster=CreateFrame("Frame","MinimapCluster",UIParent);arg1=.1;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIObjectives.anchor[2]==MinimapCluster);MinimapCluster=nil;Minimap=nil;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIObjectives.anchor[2]==UIParent and ASXUIObjectives.anchor[4]==-20)')
    def test_upcoming_guardians_use_native_lair_countdowns_and_retire_when_held(self):
        self.run_lua('view.data.sayge=nil;function AZS_GetLairs()return lairs end;lairs={{state="empty",active=false,name="Next",left=45},{state="empty",active=false,name="Later",left=61}};arg1=.1;ASXUIFramesController.scripts.OnUpdate();assert(ASXUI_FramesReadout().objectives[1]=="Next: Incoming" and ASXUI_FramesReadout().objectives[2]==nil);lairs[1]={state="asleep",active=true,name="Next",left=-1};ASXUIFramesController.scripts.OnUpdate();assert(ASXUI_FramesReadout().objectives[1]=="Defeat Next");lairs[1]={state="empty",active=false,name="Next",left=0};ASXUIFramesController.scripts.OnUpdate();assert(ASXUI_FramesReadout().objectives[1]=="Next: Arriving soon")')
    def test_guardian_objectives_share_one_quest_and_preserve_every_name(self):
        self.run_lua('view.data.sayge=nil;guardians={{id=1,name="First",hp=1},{id=2,name="Second",hp=2}};arg1=.1;ASXUIFramesController.scripts.OnUpdate();local r=ASXUI_FramesReadout();assert(table.getn(r.objectives)==1 and r.objectives[1]=="Defeat First; Defeat Second");assert(r.health=="125")')
    def test_encounter_names_are_centered_without_percentage_labels(self):
        self.run_lua('hudPrefs.bosses=true;function AZS_GetBosses()return {{id=1,name="Boss",hp=50,hpm=100}}end;guardians={};arg1=.1;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIEncounter1.value==nil and ASXUIEncounter1.title.anchor[1]=="CENTER" and ASXUI_FramesReadout().encounters.rows[1].health==.5)')
    def test_arrival_timer_has_its_own_line_only_during_the_last_thirty_seconds(self):
        self.run_lua('view.data.sayge=nil;lair={state="empty",active=false,name="Next guardian",left=45};function AZS_GetLairs()return {lair}end;arg1=.1;ASXUIFramesController.scripts.OnUpdate();local text=ASXUI_FramesReadout().objectiveTexts[1];assert(string.find(text,"Await Next guardian",1,true) and not string.find(text,"45",1,true));lair.left=30;ASXUIFramesController.scripts.OnUpdate();text=ASXUI_FramesReadout().objectiveTexts[1];assert(string.find(text,"Await Next guardian\\n    Arrives in 30 s",1,true));lair.left=31;ASXUIFramesController.scripts.OnUpdate();assert(not string.find(ASXUI_FramesReadout().objectiveTexts[1],"Arrives in",1,true))')
    def test_guardians_group_names_but_deduplicate_native_entity_ids(self):
        self.run_lua('guardians={{id=1,name="Guardian",hp=10},{id=2,name="Guardian",hp=20},{id=2,name="Guardian",hp=20}};view.data.sayge=nil;arg1=.1;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIObjectives:GetHeight()==106)')
    def test_held_lairs_include_distant_guardians_without_requiring_the_minimap(self):
        self.run_lua('function AZS_GetLairs()return {{active=true,id=99,name="Distant Guardian"},{active=false,id=0,name="Absent Guardian"}}end;guardians={};view.data.sayge=nil;Minimap:Hide();arg1=.1;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIObjectives:IsShown() and ASXUIObjectives:GetHeight()==106 and ASXUI_FramesReadout().objectives[1]=="Defeat Distant Guardian")')
    def test_allied_buffs_stay_outside_build_frame_with_native_identity_and_tooltips(self):
        self.run_lua('local spell=CreateFrame("Button","ASXOfficialParty1Spell1",PartyMemberFrame1);spell.data={owner="22"};local handler=function()end;for i=1,9 do local b=CreateFrame("Button","ASXOfficialParty1Buff"..i,PartyMemberFrame1);b.unit="party1";b.buffIndex=i;b:SetPoint("LEFT",PartyMemberFrame1,"RIGHT",i*18,0);b.scripts.OnEnter=handler end;arg1=.1;ASXUIFramesController.scripts.OnUpdate();local panel=ASXUIAllyBuild1;assert(panel:GetWidth()==100 and panel:GetHeight()==49);assert(spell.anchor[3]=="TOPLEFT");assert(ASXOfficialParty1Buff1.anchor[2]==panel and ASXOfficialParty1Buff1.anchor[3]=="TOPRIGHT" and ASXOfficialParty1Buff1.anchor[4]==6);assert(ASXOfficialParty1Buff9.anchor[4]==6 and ASXOfficialParty1Buff9.anchor[5]<ASXOfficialParty1Buff1.anchor[5]);assert(ASXOfficialParty1Buff1.unit=="party1" and ASXOfficialParty1Buff1.buffIndex==1 and ASXOfficialParty1Buff1.scripts.OnEnter==handler);ASXUI_ConfigureHud("off");ASXUIFramesController.scripts.OnUpdate();assert(ASXOfficialParty1Buff1.anchor[2]==PartyMemberFrame1 and ASXOfficialParty1Buff1.anchor[3]=="RIGHT")')
    def test_allied_panels_retain_native_owner_tooltips_and_restore_anchors(self):
        self.run_lua('local b=CreateFrame("Button","ASXOfficialParty1Spell1",PartyMemberFrame1);b.data={owner="22",text="Owner native tooltip"};b:SetPoint("TOPLEFT",PartyMemberFrame1,"TOPRIGHT",4,0);local click=function()end;b.scripts.OnEnter=click;arg1=.1;ASXUIFramesController.scripts.OnUpdate();assert(ASXUIAllyBuild1:IsShown() and b.anchor[2]==ASXUIAllyBuild1 and b.data.text=="Owner native tooltip" and b.scripts.OnEnter==click);ASXUI_ConfigureHud("off");ASXUIFramesController.scripts.OnUpdate();assert(b.anchor[2]==PartyMemberFrame1)')

if __name__=='__main__':unittest.main()
